// Generates supabase/seed.sql from the TypeScript reference data so the
// database and the demo never drift. Run: npm run gen:seed (scripts/write-seed.ts)
import { AREAS, MARKETS } from '../src/domain/market';
import { DEFAULT_CATEGORIES } from '../src/domain/categories';

const q = (v: string | null) => (v === null ? 'null' : `'${v.replace(/'/g, "''")}'`);

export function seedSql(): string {
  const lines: string[] = [
    '-- Reference data only. Generated by scripts/gen-seed.ts; edit the TypeScript source instead.',
    '-- Contains no job listings or people: production starts empty, with no fabricated activity.',
    '',
    'insert into public.markets (id, slug, name, state, timezone, active) values',
    MARKETS.map((m) => `  (${q(m.id)}, ${q(m.slug)}, ${q(m.name)}, ${q(m.state)}, ${q(m.timezone)}, ${m.active})`).join(',\n') +
      '\non conflict (id) do update set name = excluded.name, timezone = excluded.timezone, active = excluded.active;',
    '',
    'insert into public.areas (zip, market_id, neighborhood, city, lat, lng) values',
    AREAS.map((a) => `  (${q(a.zip)}, ${q(a.market_id)}, ${q(a.neighborhood)}, ${q(a.city)}, ${a.lat}, ${a.lng})`).join(',\n') +
      '\non conflict (zip) do update set neighborhood = excluded.neighborhood, city = excluded.city, lat = excluded.lat, lng = excluded.lng;',
    '',
    'insert into public.categories (id, slug, name, "group", requires_license, license_note, active, sort) values',
    DEFAULT_CATEGORIES.map((c) => `  (${q(c.id)}, ${q(c.slug)}, ${q(c.name)}, ${q(c.group)}, ${c.requires_license}, ${q(c.license_note)}, ${c.active}, ${c.sort})`).join(',\n') +
      '\non conflict (id) do nothing;',
    '',
    'insert into public.plans (code, name, monthly_listing_quota, price_cents, active) values',
    "  ('free_intro', 'Introductory (free)', 3, 0, true),",
    "  ('pay_per_post', 'Single listing', null, null, false),",
    "  ('monthly', 'Monthly, frequent posters', null, null, false)",
    'on conflict (code) do nothing;',
    '',
  ];
  return lines.join('\n');
}
